body:
const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const OPENAI_KEY   = Deno.env.get("OPENAI_API_KEY")!;

const CORS = {
  "Access-Control-Allow-Origin":  "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

// ── Types ─────────────────────────────────────────────────────────────────────

interface OrderState {
  producto:         string | null;
  tamano:           string | null;
  tipo:             string | null;
  cantidad:         number;
  adiciones:        string | null;   // null=no mencionado, ""=rechazado, "X"=pedido
  direccion:        string | null;
  pago:             string | null;
  nombre:           string | null;
  upsell_ofrecido:  boolean;
  upsell_rechazado: boolean;
  resumen_enviado:  boolean;
  last_activity:    string;
}

interface ExtractionResult {
  producto:         string | null;
  tamano:           string | null;
  tipo:             string | null;
  cantidad:         number | null;
  adiciones:        string | null;
  direccion:        string | null;
  pago:             string | null;
  nombre:           string | null;
  confirmacion:     boolean;
  upsell_rechazado: boolean;
  es_correccion:    boolean;
  _oai_error?:      boolean;
}

interface PasoConfig {
  id:    string;
  frase: string;
}

type NextAction =
  | { type: "ask_upsell"; frase: string }
  | { type: "ask_field";  field: string; frase: string }
  | { type: "show_summary" }
  | { type: "chat"; reason: string };

function emptyOrderState(): OrderState {
  return {
    producto: null, tamano: null, tipo: null, cantidad: 1,
    adiciones: null, direccion: null, pago: null, nombre: null,
    upsell_ofrecido: false, upsell_rechazado: false,
    resumen_enviado: false, last_activity: new Date().toISOString(),
  };
}

// ── Server ────────────────────────────────────────────────────────────────────

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return new Response("Method Not Allowed", { status: 405 });

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch { return new Response("OK", { status: 200 }); }

  const convId = body.convId as string;
  if (!convId) return new Response("missing convId", { status: 400 });

  try {
    await processConversation(convId);
  } catch (err) {
    console.error("delay-reply error:", err);
    try { await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { ai_typing: false }); } catch {}
  }

  return new Response("OK", { status: 200 });
});

// ── Main ──────────────────────────────────────────────────────────────────────

async function processConversation(convId: string): Promise<void> {
  // 1. Leer la entrada de la cola
  const queueRes = await sbGet(`/rest/v1/chat_ai_queue?conversation_id=eq.${convId}&processed=eq.false&limit=1`);
  const entry = queueRes?.[0] as Record<string, unknown> | undefined;
  if (!entry) return;

  const fireAt = new Date(entry.fire_at as string).getTime();

  // 2. Esperar hasta fire_at
  let attempts = 0;
  while (attempts < 10) {
    const remaining = fireAt - Date.now();
    if (remaining > 0) await sleep(Math.min(remaining + 200, 30_000));
    const freshRes = await sbGet(`/rest/v1/chat_ai_queue?conversation_id=eq.${convId}&processed=eq.false&limit=1`);
    const fresh = freshRes?.[0] as Record<string, unknown> | undefined;
    if (!fresh) return;
    if (new Date(fresh.fire_at as string).getTime() <= Date.now()) break;
    attempts++;
  }

  // 3. Marcar como procesado
  await sbPatch(`/rest/v1/chat_ai_queue?conversation_id=eq.${convId}&processed=eq.false`, { processed: true });

  // 4. Leer datos del batch
  const batchStart  = entry.batch_start as string;
  const branchId    = entry.branch_id as string;
  const tenantId    = entry.tenant_id as string;
  const fromPhone   = entry.from_phone as string;
  const phoneId     = entry.phone_id as string;
  const accessToken = entry.access_token as string;

  const msgsRes = await sbGet(
    `/rest/v1/chat_messages?conversation_id=eq.${convId}&direction=eq.in` +
    `&sent_at=gte.${encodeURIComponent(batchStart)}&order=sent_at.asc&select=id,body,external_id`
  );
  let batchMsgs = (msgsRes || []) as Array<{ id: string; body: string; external_id: string }>;
  console.log("[DBG] batchMsgs:", batchMsgs.length, batchMsgs.map(m => m.body?.slice(0,30)));

  if (!batchMsgs.length) {
    const batchStartEarly = new Date(new Date(batchStart).getTime() - 5000).toISOString();
    const retryRes = await sbGet(
      `/rest/v1/chat_messages?conversation_id=eq.${convId}&direction=eq.in` +
      `&sent_at=gte.${encodeURIComponent(batchStartEarly)}&order=sent_at.asc&select=id,body,external_id`
    );
    batchMsgs = (retryRes || []) as Array<{ id: string; body: string; external_id: string }>;
    if (!batchMsgs.length) { await setTyping(convId, false); return; }
  }

  // Detectar si todos los mensajes del batch son media (sin texto)
  const soloMediaNoTexto = batchMsgs.every(m => {
    const b = (m.body || "").trim();
    return b.startsWith("[audio]") || b.startsWith("[imagen]") || b.startsWith("[image]") ||
           b.startsWith("[sticker]") || b.startsWith("[video]") || b === "";
  });
  // ⚠ El return early se hace DESPUÉS de cargar convRow para poder revisar pago_pendiente.
  //   Ver bloque justo después del check de human_takeover (línea ~253).

  // 5. Leer config del asistente
  const cfgRes = await sbGet(`/rest/v1/ia_config?branch_id=eq.${branchId}&limit=1`);
  const cfg = cfgRes?.[0] as Record<string, unknown> | undefined;
  if (!cfg || !cfg.activo) { await setTyping(convId, false); return; }

  // 5b. Hora Colombia (UTC-5)
  const nowUtc = new Date();
  const colombiaMs = nowUtc.getTime() - (5 * 60 * 60 * 1000);
  const colDate    = new Date(colombiaMs);
  const colHourNum = colDate.getUTCHours();
  const colMinNum  = colDate.getUTCMinutes();
  const colMin     = String(colMinNum).padStart(2, "0");
  const colAmPm    = colHourNum >= 12 ? "pm" : "am";
  const colH12     = colHourNum % 12 || 12;
  const colTimeStr = `${colH12}:${colMin}${colAmPm}`;
  const colDays    = ["domingo","lunes","martes","miércoles","jueves","viernes","sábado"];
  const colDayStr  = colDays[colDate.getUTCDay()];
  const colDayKey  = ["domingo","lunes","martes","miercoles","jueves","viernes","sabado"][colDate.getUTCDay()];
  const colHHMM    = String(colHourNum).padStart(2,"0") + ":" + colMin;

  // Derivar isOpen desde cfg.horarios (comparación en minutos para evitar errores de string)
  const horariosCfg = cfg.horarios as Record<string, Record<string,unknown>> | null | undefined;
  const fmtHora     = (cfg.formato_hora as string) || "12h";
  let isOpen = false;
  let isBeforeOpen = false;
  let horaAperturaHoy = "";
  let horaCierreHoy   = "";
  if (horariosCfg) {
    const hoy = horariosCfg[colDayKey];
    if (hoy && hoy.activo) {
      const abre   = (hoy.abre   as string) || "00:00";
      const cierra = (hoy.cierra as string) || "23:59";
      const nowMin   = colHourNum * 60 + colMinNum;
      const abreMin  = parseHHMM(abre);
      const cierraMin = parseHHMM(cierra);
      isOpen       = nowMin >= abreMin && nowMin < cierraMin;
      isBeforeOpen = nowMin < abreMin;
      horaAperturaHoy = formatHora(abre, fmtHora);
      horaCierreHoy   = formatHora(cierra, fmtHora);
    }
  } else {
    const totalMinutes = colHourNum * 60 + colMinNum;
    isBeforeOpen = totalMinutes < (18 * 60 + 30);
    const isAfterClose = totalMinutes >= (22 * 60 + 30);
    isOpen = !isBeforeOpen && !isAfterClose;
    horaAperturaHoy = fmtHora === "24h" ? "18:30" : "6:30pm";
    horaCierreHoy   = fmtHora === "24h" ? "22:30" : "10:30pm";
  }

  const pedidosProg       = !!(cfg.pedidos_programados);
  const puedeTomarPedidos = isOpen || pedidosProg;
  const frases            = (cfg.frases as Record<string, string>) || {};
  const domiciliosCfg     = cfg.domicilios as Record<string, unknown> | null | undefined;

  // Calcular próximo día activo (para señal al GPT cuando cerrado)
  const proxDia = getProximoDiaActivo(horariosCfg, colDate.getUTCDay());

  // 6b. Detectar si el cliente pide la carta → enviar imágenes y salir
  const menuImagenes = (cfg.menu_imagenes as string[]) || [];
  if (menuImagenes.length > 0) {
    const combinedLower = batchMsgs.map(m => m.body.toLowerCase().trim()).join(" ");
    const menuKw = ["la carta","el menú","el menu","dame la carta","ver la carta","su carta","ver el menú","ver el menu","qué tienen de menú","muestrame la carta","muéstrame la carta","carta del restaurante","que tienen de menu","envía la carta","envia la carta","que tienes","qué tienes","que tiene","qué tiene","que tienen","qué tienen","que hay","qué hay","tienen de","qué te","que te"];
    const isExact  = ["carta","menú","menu","el menú","el menu"].includes(combinedLower);
    const wantsMenu = isExact || menuKw.some(kw => combinedLower.includes(kw));
    if (wantsMenu) {
      for (const imgUrl of menuImagenes) {
        await fetch(`https://graph.facebook.com/v22.0/${phoneId}/messages`, {
          method: "POST",
          headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" },
          body: JSON.stringify({ messaging_product: "whatsapp", to: fromPhone, recipient_type: "individual", type: "image", image: { link: imgUrl } }),
        });
        await sleep(600);
      }
      const menuFraseCfg = (cfg.menu_frase as Record<string,string>) || {};
      const followUp = menuFraseCfg.tipo === "variable"
        ? (frases.apertura || "¿Qué se te antoja? 🍟☺️")
        : (menuFraseCfg.texto || "¿Qué se te antoja? 🍟☺️");
      const waText = await fetch(`https://graph.facebook.com/v22.0/${phoneId}/messages`, {
        method: "POST",
        headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ messaging_product: "whatsapp", to: fromPhone, recipient_type: "individual", type: "text", text: { body: followUp } }),
      });
      const waSentData = await waText.json() as Record<string, unknown>;
      const sentId = ((waSentData.messages as Array<Record<string,unknown>>)?.[0]?.id as string) || "";
      await sbPost(`/rest/v1/chat_messages`, { conversation_id: convId, tenant_id: tenantId, direction: "out", body: followUp, delivery_status: "sent", external_id: sentId || null, sent_at: new Date().toISOString() });
      await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: followUp, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
      return;
    }
  }

  // 7. Cargar menú
  const menuText = await buildMenuText(branchId);

  // 8. Leer estado de la conversación
  const convRes  = await sbGet(`/rest/v1/chat_conversations?id=eq.${convId}&select=contact_name,human_takeover,pago_pendiente,sin_nomenclatura,pending_order_data&limit=1`);
  const convRow  = convRes?.[0] as Record<string, unknown> | undefined;
  const senderName = (convRow?.contact_name as string) || fromPhone;
  const sinNomenclaturaCliente = !!(convRow?.sin_nomenclatura);

  if (convRow?.human_takeover) {
    console.log("human_takeover activo para conv", convId, "— bot silenciado");
    await setTyping(convId, false);
    return;
  }

  // ── Mensajes no-texto: responder AHORA que ya sabemos pago_pendiente ─────────
  const hasImagenBatch = batchMsgs.some(m => (m.body||"").startsWith("[imagen]") || (m.body||"").startsWith("[image]"));
  if (soloMediaNoTexto) {
    if (convRow?.pago_pendiente && hasImagenBatch) {
      // Imagen enviada mientras espera verificación → dejar fluir al bloque verify-transfer (línea ~878)
      console.log("[MEDIA] imagen con pago_pendiente=true — pasando a verify-transfer");
    } else {
      const mediaMsg = "¡Hola! Por el momento solo puedo atenderte por texto. ¿En qué te puedo ayudar? 😊";
      await sendWaAndSave(convId, tenantId, mediaMsg, fromPhone, phoneId, accessToken);
      await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, {
        last_message: mediaMsg, last_message_at: new Date().toISOString(),
        last_sender: "agent", last_read: false, ai_typing: false,
      });
      return;
    }
  }

  // ══════════════════════════════════════════════════════════════════════════════
  // 9. MÁQUINA DE ESTADOS — solo cuando el restaurante puede tomar pedidos
  // ══════════════════════════════════════════════════════════════════════════════
  let inOrderWait      = false;  // true = resumen ya enviado, esperando confirmación → GPT modo simple
  let latestOrderState: OrderState | null = null;

  if (puedeTomarPedidos && !(convRow?.pago_pendiente && soloMediaNoTexto)) {
    // 9a. Cargar estado existente con check de timeout
    const rawState   = convRow?.pending_order_data as OrderState | null | undefined;
    const timeoutMin = (cfg.pedido_timeout_minutos as number) || 45;
    const isTimedOut = rawState?.last_activity
      && (Date.now() - new Date(rawState.last_activity).getTime()) > timeoutMin * 60_000;
    const existingState: OrderState = (rawState && !isTimedOut) ? rawState : emptyOrderState();

    // 9b. Texto del cliente (sin imágenes)
    const clienteTexto = batchMsgs
      .map(m => m.body)
      .filter(b => !b.startsWith("[imagen]") && !b.startsWith("[image]"))
      .join("\n");

    // Últimos mensajes del bot para contexto de extracción
    const histCtxRes = await sbGet(
      `/rest/v1/chat_messages?conversation_id=eq.${convId}&sent_at=lt.${encodeURIComponent(batchStart)}` +
      `&order=sent_at.desc&limit=4&select=direction,body`
    );
    const histCtx = ((histCtxRes || []) as Array<{ direction: string; body: string }>).reverse();

    // 9c. Extraer datos del pedido
    let extracted = await extractOrderData(clienteTexto, histCtx, menuText, cfg);
    if ((extracted as Record<string, unknown>)._oai_error) {
      const fallback = "Disculpa, tuvimos un problema técnico. Intenta de nuevo en un momento 🙏";
      await sendWaAndSave(convId, tenantId, fallback, fromPhone, phoneId, accessToken);
      await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: fallback, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
      return;
    }
    console.log("[ORDER] extracted:", JSON.stringify(extracted));

    // 9c-bis. Override con código determinístico — más confiable que GPT para flags críticos
    const textoLow = clienteTexto.toLowerCase().trim();

    // 1. Confirmación del resumen: keywords exactas antes que GPT
    if (existingState.resumen_enviado && !extracted.confirmacion) {
      const confirmKw = ["sí","si","dale","listo","ok","claro","perfecto","correcto","confirmado","confirmo","acepto","va","bueno","sip","ya","de una","hagalo","hágalo","vamos","afirmativo","exacto","eso"];
      if (confirmKw.some(kw => textoLow === kw || textoLow === kw + "." || textoLow === kw + "!")) {
        extracted = { ...extracted, confirmacion: true };
        console.log("[ORDER] confirmacion forzada por código");
      }
    }

    // 2. Rechazo de upsell: código detecta antes que GPT
    if (existingState.upsell_ofrecido && !existingState.upsell_rechazado && !extracted.upsell_rechazado) {
      const rechazoKw = ["no","no gracias","no quiero","así está","sin adicional","solo eso","nada más","nada mas","sin nada","eso es todo","no necesito","no, gracias"];
      if (rechazoKw.some(kw => textoLow === kw || textoLow === kw + "." || textoLow.startsWith("no "))) {
        extracted = { ...extracted, upsell_rechazado: true, adiciones: "" };
        console.log("[ORDER] upsell_rechazado forzado por código");
      }
    }

    // 3. "Para llevar": detectar en mensaje original, no solo en lo que GPT extrajo
    const paraLlevarKw = ["para llevar","a recoger","voy a recoger","paso a recoger","lo recojo","para recoger"];
    if (paraLlevarKw.some(kw => textoLow.includes(kw))) {
      extracted = { ...extracted, direccion: "para llevar" };
      console.log("[ORDER] para_llevar detectado por código");
    }

    // 5. Correcciones explícitas a un campo → override directo (más fiable que GPT)
    {
      const mDir = clienteTexto.match(
        /(?:cambia?r?\s+(?:la\s+)?direcci[oó]n\s+(?:a|por)\s*|la\s+direcci[oó]n\s+es\s*|direcci[oó]n:\s*)(.{5,})/i
      );
      if (mDir) {
        extracted = { ...extracted, direccion: mDir[1].trim(), es_correccion: true };
        console.log("[ORDER] override direccion:", mDir[1].trim());
      }
      const mPago = clienteTexto.match(
        /(?:cambia?r?\s+(?:el\s+)?pago\s+(?:a|por)\s*|el\s+pago\s+es\s*|pago\s+en\s*|prefiero\s+(?:pagar\s+en\s*)?|voy\s+a\s+pagar\s+(?:en\s+)?)(\w+)/i
      );
      if (mPago) {
        extracted = { ...extracted, pago: mPago[1].trim().toLowerCase(), es_correccion: true };
        console.log("[ORDER] override pago:", mPago[1].trim());
      }
      const mNombre = clienteTexto.match(
        /(?:me\s+llamo\s*|a\s+nombre\s+de\s*|el\s+nombre\s+es\s*|cambia?r?\s+(?:el\s+)?nombre\s+(?:a|por)\s*)([A-ZÁÉÍÓÚÑa-záéíóúñ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑa-záéíóúñ][a-záéíóúñ]+)?)/i
      );
      if (mNombre) {
        extracted = { ...extracted, nombre: mNombre[1].trim(), es_correccion: true };
        console.log("[ORDER] override nombre:", mNombre[1].trim());
      }
      const mTamano = clienteTexto.match(
        /(?:cambia?r?\s+(?:el\s+)?tama[ñn]o\s+(?:a|por)\s*)(familiar|personal|[úu]nico|litro|1\.5\s+litros?)/i
      );
      if (mTamano) {
        extracted = { ...extracted, tamano: mTamano[1].trim().toLowerCase(), es_correccion: true };
        console.log("[ORDER] override tamano:", mTamano[1].trim());
      }
    }

    // 4. Múltiples productos en un solo mensaje → pedir de uno en uno
    // Solo si NO hay producto ya establecido en estado (primer mensaje con pedido)
    if (puedeTomarPedidos && !existingState.resumen_enviado && !existingState.producto && extracted.producto) {
      // Detecta: "y una/un/2/otro X" o "también quiero X"
      const multiItemRegex = /\b(y\s+(un[ao]?\s+|[0-9]+\s+|otr[ao]?\s+)\w{4,}|también\s+(quiero?|quisiera|dame)\s+(un[ao]?\s+)?\w{4,})/i;
      if (multiItemRegex.test(clienteTexto)) {
        const frasesObjM = (cfg.frases as Record<string,string>) || {};
        const multiMsg = frasesObjM.multi_producto || "Para atenderte bien, tomamos los pedidos de uno en uno 😊 ¿Con cuál empezamos?";
        console.log("[ORDER] multi-producto detectado");
        await sendWaAndSave(convId, tenantId, multiMsg, fromPhone, phoneId, accessToken);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: multiMsg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
        return;
      }
    }

    // 9d. Merge no-destructivo
    const newState = mergeOrderState(existingState, extracted);
    console.log("[ORDER] newState:", JSON.stringify(newState));

    // 9e. Guardar estado actualizado
    await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: newState });

    // 9f. Manejar confirmación del resumen
    if (extracted.confirmacion && existingState.resumen_enviado) {
      const pago = (newState.pago || "").toLowerCase();
      const esTransferencia = pago.includes("nequi") || pago.includes("daviplata") || pago.includes("transfer");

      if (esTransferencia) {
        const compMsg = frases.esperar_comprobante || "Quedó pendiente del comprobante para poderte preparar ☺️";
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pago_pendiente: true });
        await sendWaAndSave(convId, tenantId, compMsg, fromPhone, phoneId, accessToken);
        // Enviar QR si configurado
        const pagosCfg = cfg.pagos as Record<string, unknown> | null | undefined;
        const qrUrl    = (pagosCfg?.qr_imagen_url as string) || "";
        const qrTxt    = (pagosCfg?.qr_texto      as string) || "";
        if (qrUrl) {
          await sleep(600);
          const qrRes = await fetch(`https://graph.facebook.com/v22.0/${phoneId}/messages`, {
            method: "POST",
            headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" },
            body: JSON.stringify({ messaging_product: "whatsapp", to: fromPhone, recipient_type: "individual", type: "image", image: { link: qrUrl, caption: qrTxt || undefined } }),
          });
          if (qrRes.ok) {
            const qrSent  = await qrRes.json() as Record<string, unknown>;
            const qrMsgId = ((qrSent.messages as Array<Record<string,unknown>>)?.[0]?.id as string) || "";
            await sbPost(`/rest/v1/chat_messages`, { conversation_id: convId, tenant_id: tenantId, direction: "out", body: `[imagen] ${qrUrl}`, delivery_status: "sent", external_id: qrMsgId || null, sent_at: new Date().toISOString() });
          }
        }
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: compMsg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
        return;

      } else {
        // Efectivo: verificar dirección y crear pedido
        const clasif = clasificarDireccion(newState.direccion || "", domiciliosCfg, sinNomenclaturaCliente);

        if (clasif.tipo === "rechazado") {
          const msg = "Lo sentimos, no podemos hacer domicilios a ese lugar 😊 Si querés podés pasar a recoger tu pedido (para llevar).";
          await sendWaAndSave(convId, tenantId, msg, fromPhone, phoneId, accessToken);
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: msg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
          return;
        }

        if (clasif.tipo === "incompleta") {
          const msg = "¿Me das el número completo de la dirección? Por ejemplo: Carrera 5 # 23-45 ☺️";
          newState.direccion      = null;
          newState.resumen_enviado = false;
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: newState });
          await sendWaAndSave(convId, tenantId, msg, fromPhone, phoneId, accessToken);
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: msg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
          return;
        }

        if (clasif.tipo === "publico" && clasif.requierePagoAdelantado) {
          const msg = "Para domicilios a establecimientos o lugares públicos, el pago debe ser por adelantado (Nequi o Daviplata) 😊 ¿Cómo nos lo harías llegar?";
          newState.pago           = null;
          newState.resumen_enviado = false;
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: newState });
          await sendWaAndSave(convId, tenantId, msg, fromPhone, phoneId, accessToken);
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: msg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
          return;
        }

        const esParaLlevar = clasif.tipo === "para_llevar";
        const domiPrecio   = esParaLlevar ? 0 : lookupDomiPrice(newState.direccion || "", domiciliosCfg);

        if (!esParaLlevar && domiPrecio === null) {
          await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { domi_precio_pendiente: true, human_takeover: true });
          await setTyping(convId, false);
          return;
        }

        try {
          const orderArgs = buildOrderArgs(newState, domiPrecio ?? 0);
          const orderId   = await createWhatsappOrder(orderArgs, branchId, tenantId, fromPhone);
          console.log("[ORDER] Pedido creado:", orderId);
        } catch (err) {
          console.error("[ORDER] Error creando pedido:", err);
        }

        const closeMsg = frases.cierre_pedido || "En un momento enviamos tu pedido 🍟 ¡Con muchísimo gusto!";
        await sendWaAndSave(convId, tenantId, closeMsg, fromPhone, phoneId, accessToken);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, {
          pending_order_data: null,
          last_message: closeMsg, last_message_at: new Date().toISOString(),
          last_sender: "agent", last_read: false, ai_typing: false,
        });
        return;
      }
    }

    // 9g. Si hay producto → correr decisor de pasos
    if (newState.producto) {
      latestOrderState = newState;
      const pasos  = getPasos(cfg, frases);
      const action = decideAction(newState, pasos, menuText);
      console.log("[ORDER] action:", action.type);

      if (action.type === "ask_upsell") {
        newState.upsell_ofrecido = true;
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: newState });
        await sendWaAndSave(convId, tenantId, action.frase, fromPhone, phoneId, accessToken);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: action.frase, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
        return;

      } else if (action.type === "ask_field") {
        await sendWaAndSave(convId, tenantId, action.frase, fromPhone, phoneId, accessToken);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: action.frase, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
        return;

      } else if (action.type === "show_summary") {
        const sumMsg = await buildSummaryFromState(newState, cfg, branchId, domiciliosCfg);
        newState.resumen_enviado = true;
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: newState });
        await sendWaAndSave(convId, tenantId, sumMsg, fromPhone, phoneId, accessToken);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: sumMsg, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
        return;

      } else {
        // "chat" → resumen enviado, esperando confirmación → GPT en modo simple
        inOrderWait = true;
      }
    }
  }

  // ══════════════════════════════════════════════════════════════════════════════
  // 10. FLUJO GPT NORMAL (chat general, cerrado, o esperando confirmación)
  // ══════════════════════════════════════════════════════════════════════════════

  // Historial previo
  const histRes = await sbGet(
    `/rest/v1/chat_messages?conversation_id=eq.${convId}&sent_at=lt.${encodeURIComponent(batchStart)}` +
    `&order=sent_at.desc&limit=25&select=direction,body`
  );
  const history = ((histRes || []) as Array<{ direction: string; body: string }>).reverse();

  // Detectar upsell rechazado en historial (para buildSystemPrompt)
  const upsellKwBot = ["adicionar", "super queso", "salchicha ranchera", "salsas especiales", "adiciones"];
  const rechazoKw   = ["no gracias", "no quiero", "así está bien", "no, gracias", "no quiero nada", "solo eso", "sin adicional"];
  let upsellYaOfrecido = false;
  let upsellRechazado  = false;
  for (let _i = 0; _i < history.length; _i++) {
    const _m = history[_i];
    const _bl = (_m.body || "").toLowerCase();
    if (_m.direction === "out" && upsellKwBot.some(kw => _bl.includes(kw))) upsellYaOfrecido = true;
    if (upsellYaOfrecido && _m.direction === "in") {
      const _bt = _bl.trim();
      if (rechazoKw.some(kw => _bt.includes(kw)) || _bt === "no" || _bt === "no." || _bt === "noo" || _bt === "no,") upsellRechazado = true;
    }
  }

  // Textos de soporte
  const horariosText   = buildHorariosText(cfg.horarios as Record<string, unknown> | null | undefined, fmtHora);
  const pagosText      = buildPagosText(cfg.pagos as Record<string, unknown> | null | undefined);
  const domiciliosText = buildDomiciliosText(domiciliosCfg);
  const rechazarLugPubl   = domiciliosCfg?.rechazar_lugares_publicos !== false;
  const pagoAdelanLugPubl = domiciliosCfg?.pago_adelantado_lugares_publicos !== false;

  // System prompt: simplificado si estamos esperando confirmación del resumen
  const systemPrompt = inOrderWait && latestOrderState
    ? buildOrderWaitPrompt(latestOrderState, cfg)
    : buildSystemPrompt(
        cfg, senderName, menuText, horariosText, pagosText, domiciliosText,
        batchMsgs.length, colTimeStr, colDayStr, isOpen, isBeforeOpen, pedidosProg,
        sinNomenclaturaCliente, rechazarLugPubl, pagoAdelanLugPubl, upsellRechazado,
        horaAperturaHoy, horaCierreHoy, proxDia
      );

  // Detectar si el historial está contaminado con mensajes del estado OPUESTO al actual.
  // Si el bot estuvo diciendo "cerrado/no hay servicio" y ahora está abierto (o viceversa),
  // no pasar ese historial a GPT — que responda fresco con solo el system prompt actual.
  const lastBotInHistory = [...history].reverse().find(m => m.direction === "out")?.body || "";
  const historicoDeciaAbierto  = /atenderemos|pedido|listo|enviamos|¿qué se te antoja|bienvenid/i.test(lastBotInHistory);
  const historicoDeciaCerrado  = /no hay servicio|a partir de las|no estamos atendiendo|cerrado|fuera de horario/i.test(lastBotInHistory);
  const historialContaminado   = (isOpen && historicoDeciaCerrado) || (!isOpen && historicoDeciaAbierto);
  const historialFiltrado      = historialContaminado ? [] : history;

  // Armar mensajes
  const messages: Array<{ role: string; content: string }> = [
    { role: "system", content: systemPrompt },
  ];
  for (const h of historialFiltrado) {
    if (h.body) messages.push({ role: h.direction === "in" ? "user" : "assistant", content: h.body });
  }
  if (batchMsgs.length === 1) {
    messages.push({ role: "user", content: batchMsgs[0].body });
  } else {
    const combined = batchMsgs.map((m, i) => `[${i + 1}] id:${m.external_id} | ${m.body}`).join("\n");
    messages.push({ role: "user", content: combined });
  }

  // Tools solo cuando puede tomar pedidos Y no estamos esperando confirmación
  const useTools = puedeTomarPedidos && !inOrderWait;
  const responseFormat = (!useTools && batchMsgs.length > 1) ? { type: "json_object" } : undefined;

  const CREAR_PEDIDO_TOOL = {
    type: "function",
    function: {
      name: "crear_pedido",
      description: "Crea el pedido en el sistema Cobra POS. Llamar SOLO cuando el cliente haya confirmado explícitamente (dijo sí, correcto, dale, confirmo, etc.) al resumen del pedido. Requiere tener los 4 datos completos.",
      parameters: {
        type: "object",
        properties: {
          cliente:    { type: "string",  description: "Nombre del cliente" },
          direccion:  { type: "string",  description: "Dirección de entrega o 'para llevar'" },
          pago:       { type: "string",  description: "Método de pago: efectivo, nequi, daviplata, etc." },
          mensaje:    { type: "string",  description: "Mensaje de confirmación para enviarle al cliente" },
          productos: {
            type: "array",
            items: {
              type: "object",
              properties: {
                nombre:   { type: "string",  description: "Nombre del producto" },
                tamano:   { type: "string",  description: "Personal, Familiar, Unico, Litro o 1.5 Litros" },
                tipo:     { type: "string",  description: "Mixta, Carne o Pollo — solo para Premium y Maicitos Especial" },
                cantidad: { type: "integer", description: "Cantidad" },
              },
              required: ["nombre", "tamano", "cantidad"],
            },
          },
        },
        required: ["cliente", "productos", "direccion", "pago", "mensaje"],
      },
    },
  };

  const OAI_FALLBACK = "Disculpa, tuvimos un problema técnico. Intenta de nuevo en un momento 🙏";
  const oaiBody = JSON.stringify({
    model: "gpt-4o-mini",
    messages,
    max_tokens: 1000,
    temperature: 0.7,
    ...(useTools ? { tools: [CREAR_PEDIDO_TOOL], tool_choice: "auto" } : {}),
    ...(responseFormat ? { response_format: responseFormat } : {}),
  });

  let oaiRes: Response | null = null;
  for (let oaiAttempt = 0; oaiAttempt < 2; oaiAttempt++) {
    if (oaiAttempt > 0) await sleep(1200);
    try {
      oaiRes = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: { "Authorization": `Bearer ${OPENAI_KEY}`, "Content-Type": "application/json" },
        body: oaiBody,
      });
      if (oaiRes.ok) break;
      console.error(`OpenAI intento ${oaiAttempt+1} status:`, oaiRes.status, await oaiRes.text());
      oaiRes = null;
    } catch (fetchErr) {
      console.error(`OpenAI intento ${oaiAttempt+1} fetch error:`, fetchErr);
      oaiRes = null;
    }
  }

  if (!oaiRes) {
    await sendWaAndSave(convId, tenantId, OAI_FALLBACK, fromPhone, phoneId, accessToken);
    await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { last_message: OAI_FALLBACK, last_message_at: new Date().toISOString(), last_sender: "agent", last_read: false, ai_typing: false });
    return;
  }

  const oaiData   = await oaiRes.json() as Record<string, unknown>;
  const choice    = (oaiData.choices as Array<Record<string,unknown>>)?.[0];
  const message   = choice?.message as Record<string,unknown> | undefined;
  const toolCalls = message?.tool_calls as Array<Record<string,unknown>> | undefined;
  const rawReplyDbg = (message?.content as string || "").trim();
  console.log("[DBG] toolCalls:", toolCalls?.length, "rawReply len:", rawReplyDbg.length, "first50:", rawReplyDbg.slice(0,50));

  // Parsear respuesta
  type RespItem = { quote_id?: string; text: string };
  let responses: RespItem[] = [];
  let pendingOrder: Record<string, unknown> | null = null;

  // Tool call de crear_pedido
  if (toolCalls?.length) {
    const tc = toolCalls.find(t => (t.function as Record<string,unknown>)?.name === "crear_pedido");
    if (tc) {
      try {
        const args = JSON.parse((tc.function as Record<string,unknown>).arguments as string) as Record<string,unknown>;
        pendingOrder = args;
        const confirmMsg = (args.mensaje as string) || "¡Pedido creado! 🍟 En un momento lo preparamos.";
        responses = [{ text: confirmMsg }];
      } catch {
        console.error("Error parseando args de crear_pedido");
      }
    }
  }

  // Texto libre
  if (!responses.length) {
    const rawReply = (message?.content as string || "").trim();
    if (!rawReply) {
      console.warn("GPT devolvió rawReply vacío");
      responses = [{ text: "Disculpa, no entendí. ¿Puedes repetirme?" }];
    } else if (!useTools && batchMsgs.length > 1) {
      try {
        const parsed = JSON.parse(rawReply) as { type?: string; responses?: RespItem[] };
        responses = Array.isArray(parsed.responses) ? parsed.responses : [{ text: rawReply }];
      } catch {
        responses = [{ text: rawReply }];
      }
    } else {
      responses = [{ text: rawReply }];
    }
  }

  // Bloque isResumen — solo cuando NO está activa la máquina de estados
  if (!pendingOrder && puedeTomarPedidos && !inOrderWait && responses.length === 1 && responses[0].text) {
    const draft = responses[0].text;
    const isResumen = draft.includes("🍟") && draft.includes("📍") && draft.includes("💳");
    if (isResumen) {
      try {
        const confirmFrase   = frases.resumen_confirmacion      || "¿Lo confirmamos o hay algo que cambiar?";
        const totalDescFrase = frases.resumen_total_desconocido || "ya te confirmamos el total ☺️🍟";
        const plantilla      = (cfg.resumen_plantilla as string) ||
          "Listo! Tu pedido quedaría así:\n🍟 {{cantidad}}x {{producto}} {{tamano}}{{adiciones}}\n📍 {{direccion}}\n💳 {{pago}}\n{{linea_total}}\n{{confirmacion}}";

        const zonas = ((domiciliosCfg?.zonas as Array<{ nombre: string; precio: number }>) || []);

        const extractRes = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: { "Authorization": `Bearer ${OPENAI_KEY}`, "Content-Type": "application/json" },
          body: JSON.stringify({
            model: "gpt-4o-mini",
            messages: [
              {
                role: "system",
                content: `Extrae los datos del pedido de esta conversación y devuelve SOLO un JSON con estos campos exactos:
{
  "producto": "nombre del producto sin tamaño (ej: Salchipapa Premium Mixta)",
  "tamano": "tamaño del producto (ej: Personal, Familiar)",
  "cantidad": 1,
  "adiciones": " + nombre_adicion" (con espacio al inicio; cadena vacía "" si el cliente NO pidió adiciones explícitamente),
  "direccion": "dirección completa de entrega",
  "barrio": "solo el nombre del barrio para buscar en la tabla de precios",
  "pago": "método de pago (ej: Efectivo, Nequi)",
  "nombre_pedido": "nombre para recibir el pedido — cadena vacía si no lo dijo",
  "precio_producto_num": 28000
}
MENÚ:\n${menuText}`,
              },
              ...messages.slice(1),
            ],
            max_tokens: 300,
            response_format: { type: "json_object" },
          }),
        });

        let extracted: Record<string, unknown> = {};
        try {
          const extractData = await extractRes.json() as Record<string, unknown>;
          extracted = JSON.parse(
            String(((extractData.choices as Array<Record<string,unknown>>)?.[0]
              ?.message as Record<string,unknown>)?.content || "{}")
          ) as Record<string, unknown>;
        } catch (extractErr) {
          console.error("Error en extracción de resumen:", extractErr);
        }

        const barrioRaw = String(extracted.barrio || "").toLowerCase().trim();
        const zona = zonas.find(z =>
          barrioRaw.includes(z.nombre.toLowerCase()) || z.nombre.toLowerCase().includes(barrioRaw)
        );
        const fmtPeso = (n: number) => "$" + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
        const precioProductoNum  = Number(extracted.precio_producto_num) || 0;
        const precioDomicilioNum = zona ? zona.precio : 0;
        const precioTotalNum     = precioProductoNum + precioDomicilioNum;

        let lineaTotal: string;
        if (zona && precioProductoNum > 0) {
          lineaTotal = `Total: ${fmtPeso(precioProductoNum)} + ${fmtPeso(precioDomicilioNum)} del domicilio = ${fmtPeso(precioTotalNum)} :)`;
        } else {
          lineaTotal = totalDescFrase;
        }

        const nombrePedido = String(extracted.nombre_pedido || "").trim();
        if (!nombrePedido) {
          responses = [{ text: frases.nombre_recibir || "¿A nombre de quién se recibe el pedido? 🍟" }];
        } else {
          const result = plantilla
            .replace(/\{\{cantidad\}\}/g,        String(extracted.cantidad   || 1))
            .replace(/\{\{producto\}\}/g,         String(extracted.producto   || ""))
            .replace(/\{\{tamano\}\}/g,           String(extracted.tamano     || ""))
            .replace(/\{\{adiciones\}\}/g,        String(extracted.adiciones  || ""))
            .replace(/\{\{direccion\}\}/g,        String(extracted.direccion  || ""))
            .replace(/\{\{pago\}\}/g,             String(extracted.pago       || ""))
            .replace(/\{\{precio_producto\}\}/g,  precioProductoNum > 0 ? fmtPeso(precioProductoNum) : "")
            .replace(/\{\{precio_domicilio\}\}/g, zona ? fmtPeso(precioDomicilioNum) : "")
            .replace(/\{\{precio_total\}\}/g,     (zona && precioProductoNum > 0) ? fmtPeso(precioTotalNum) : "")
            .replace(/\{\{nombre\}\}/g,           nombrePedido)
            .replace(/\{\{linea_total\}\}/g,      lineaTotal)
            .replace(/\{\{confirmacion\}\}/g,     confirmFrase);
          responses = [{ text: result }];
        }
      } catch (resumenErr) {
        console.error("ERROR en bloque isResumen:", resumenErr);
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pending_order_data: { _dbg: "RESUMEN_THROW", err: String(resumenErr) } });
        responses = [{ text: responses[0]?.text || "Disculpa, hubo un error al procesar el resumen." }];
      }
    }
  }

  // Confirmación legacy (para cuando no hay máquina de estados activa)
  if (!pendingOrder && puedeTomarPedidos && !inOrderWait) {
    const latestUserText = batchMsgs[batchMsgs.length - 1]?.body?.toLowerCase?.() || "";
    const CONFIRM_WORDS  = ["sí","si","correcto","dale","perfecto","claro",
                             "de acuerdo","afirmativo","está bien","confirmo","exacto","así es"];
    const isConfirmMsg   = CONFIRM_WORDS.some(w =>
      latestUserText === w || latestUserText.startsWith(w + " ") ||
      latestUserText.endsWith(" " + w) || latestUserText.includes(" " + w + " "));

    const allBotMessages = messages.filter(m => m.role === "assistant");
    const lastBotMsg = allBotMessages.length > 0
      ? String(allBotMessages[allBotMessages.length - 1].content || "")
      : "";
    const hasSummary = lastBotMsg.includes("¿Lo confirmamos") ||
                       lastBotMsg.includes("¿Todo correcto?") ||
                       lastBotMsg.includes("Confirmemos") ||
                       lastBotMsg.includes("correcto?") ||
                       (lastBotMsg.includes("total") && lastBotMsg.includes("$") && (lastBotMsg.includes("confirmamos") || lastBotMsg.includes("correcto")));

    if (isConfirmMsg && hasSummary && latestUserText.length <= 80) {
      console.log("Confirmación detectada (legacy) — forzando extracción con tool_choice required");
      const extractRes = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: { "Authorization": `Bearer ${OPENAI_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "gpt-4o-mini",
          messages: [
            { role: "system", content: "El cliente acaba de confirmar su pedido. Extrae TODOS los datos del pedido de la conversación (nombre del cliente, productos con tamaño, dirección, método de pago) y llama a la función crear_pedido() ahora mismo. El campo 'mensaje' debe ser un mensaje de confirmación breve y amigable." },
            ...messages.slice(1),
          ],
          max_tokens: 500,
          tools: [CREAR_PEDIDO_TOOL],
          tool_choice: { type: "function", function: { name: "crear_pedido" } },
        }),
      });

      if (extractRes.ok) {
        const extractData = await extractRes.json() as Record<string, unknown>;
        const extractMsg  = (extractData.choices as Array<Record<string,unknown>>)?.[0]
                              ?.message as Record<string,unknown> | undefined;
        const extractTc   = (extractMsg?.tool_calls as Array<Record<string,unknown>>)?.[0];
        if (extractTc && (extractTc.function as Record<string,unknown>)?.name === "crear_pedido") {
          try {
            pendingOrder = JSON.parse((extractTc.function as Record<string,unknown>).arguments as string) as Record<string,unknown>;
            console.log("Pedido extraído (legacy):", JSON.stringify(pendingOrder));
          } catch {
            console.error("Error parseando args legacy");
          }
        }
      }
    }
  }

  // Crear pedido (pendingOrder del flujo GPT legacy)
  let shouldSendQr = false;
  let qrImageUrl   = "";
  let qrTexto      = "";
  if (pendingOrder) {
    try {
      const pagoMetodo      = String(pendingOrder.pago || "").toLowerCase();
      const esTransferencia = pagoMetodo.includes("transfer") || pagoMetodo.includes("nequi") || pagoMetodo.includes("daviplata");

      if (esTransferencia) {
        await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { pago_pendiente: true, pending_order_data: pendingOrder });
        const pagosCfg = cfg.pagos as Record<string, unknown> | null | undefined;
        qrImageUrl   = (pagosCfg?.qr_imagen_url as string) || "";
        qrTexto      = (pagosCfg?.qr_texto      as string) || "";
        shouldSendQr = !!qrImageUrl;
      } else {
        const clasif = clasificarDireccion(String(pendingOrder.direccion || ""), domiciliosCfg, sinNomenclaturaCliente);

        if (clasif.tipo === "rechazado") {
          responses = [{ text: "Lo sentimos, no podemos hacer domicilios a ese lugar 😊 Si querés podés pasar a recoger tu pedido (para llevar)." }];
          pendingOrder = null;
        } else if (clasif.tipo === "incompleta") {
          responses = [{ text: "¿Me das el número completo de la dirección? Por ejemplo: Carrera 5 # 23-45 ☺️" }];
          pendingOrder = null;
        } else if (clasif.tipo === "publico" && clasif.requierePagoAdelantado) {
          const pagoMet    = String(pendingOrder.pago || "").toLowerCase();
          const esEfectivo = !pagoMet.includes("nequi") && !pagoMet.includes("daviplata") && !pagoMet.includes("transfer");
          if (esEfectivo) {
            responses = [{ text: "Para domicilios a establecimientos o lugares públicos, el pago debe ser por adelantado (Nequi o Daviplata) 😊 ¿Cómo nos lo harías llegar?" }];
            pendingOrder = null;
          } else {
            const domiPrecio = lookupDomiPrice(String(pendingOrder.direccion || ""), domiciliosCfg);
            if (domiPrecio === null) {
              await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { domi_precio_pendiente: true, human_takeover: true, pending_order_data: { ...pendingOrder, domi_precio_pendiente: true } });
            } else {
              await createWhatsappOrder({ ...pendingOrder, domi_precio: domiPrecio }, branchId, tenantId, fromPhone);
            }
          }
        } else {
          const esParaLlevar = clasif.tipo === "para_llevar";
          const domiPrecio   = esParaLlevar ? 0 : lookupDomiPrice(String(pendingOrder.direccion || ""), domiciliosCfg);
          if (!esParaLlevar && domiPrecio === null) {
            await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { domi_precio_pendiente: true, human_takeover: true, pending_order_data: { ...pendingOrder, domi_precio_pendiente: true } });
          } else {
            await createWhatsappOrder({ ...pendingOrder, domi_precio: domiPrecio }, branchId, tenantId, fromPhone);
          }
        }
      }
    } catch (err) {
      console.error("Error procesando pedido WhatsApp:", err);
    }
  }

  // Verificar comprobante de transferencia si hay imagen y pago_pendiente
  const convPagoPendiente = convRow?.pago_pendiente as boolean | undefined;
  const latestMsg = batchMsgs[batchMsgs.length - 1];
  const hasImage  = latestMsg?.body?.startsWith("[imagen]") || latestMsg?.body?.startsWith("[image]");

  if (convPagoPendiente && hasImage) {
    try {
      await fetch(`${SUPABASE_URL}/functions/v1/verify-transfer`, {
        method: "POST",
        headers: { "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({ conversation_id: convId }),
      });
      responses = [];
    } catch (err) {
      console.error("Error llamando verify-transfer:", err);
      responses = [{ text: "Recibimos tu comprobante, en un momento lo verificamos y confirmamos tu pedido 🙏" }];
    }
  }

  // Enviar respuestas por WhatsApp
  console.log("[DBG] responses.length:", responses.length, "pendingOrder:", !!pendingOrder);
  for (const resp of responses) {
    const text = resp.text?.trim();
    if (!text) continue;

    const waBody: Record<string, unknown> = {
      messaging_product: "whatsapp", to: fromPhone,
      recipient_type: "individual", type: "text", text: { body: text },
    };
    if (resp.quote_id) waBody.context = { message_id: resp.quote_id };

    const waRes = await fetch(`https://graph.facebook.com/v22.0/${phoneId}/messages`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify(waBody),
    });

    if (!waRes.ok) { console.error("WA send error:", await waRes.text()); continue; }
    const waSent = await waRes.json() as Record<string, unknown>;
    const sentId = ((waSent.messages as Array<Record<string,unknown>>)?.[0]?.id as string) || "";
    await sbPost(`/rest/v1/chat_messages`, { conversation_id: convId, tenant_id: tenantId, direction: "out", body: text, delivery_status: "sent", external_id: sentId || null, sent_at: new Date().toISOString() });

    if (responses.length > 1) await sleep(400);
  }

  // Domi pendiente
  const botDijoDomiPendiente = responses.some(r => (r.text || "").includes("ya te confirmamos el total"));
  const esResumenPidiendo    = responses.some(r => {
    const t = r.text || "";
    return t.includes("¿Lo confirmamos") || t.includes("¿Todo correcto?") || t.includes("correcto?") || t.includes("Confirmemos");
  });
  if (botDijoDomiPendiente) {
    await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, { domi_precio_pendiente: true, ...(esResumenPidiendo ? {} : { human_takeover: true }) });
  }

  // QR transferencia
  if (shouldSendQr) {
    await sleep(600);
    const qrRes = await fetch(`https://graph.facebook.com/v22.0/${phoneId}/messages`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ messaging_product: "whatsapp", to: fromPhone, recipient_type: "individual", type: "image", image: { link: qrImageUrl, caption: qrTexto || undefined } }),
    });
    if (qrRes.ok) {
      const qrSent  = await qrRes.json() as Record<string, unknown>;
      const qrMsgId = ((qrSent.messages as Array<Record<string,unknown>>)?.[0]?.id as string) || "";
      await sbPost(`/rest/v1/chat_messages`, { conversation_id: convId, tenant_id: tenantId, direction: "out", body: `[imagen] ${qrImageUrl}`, delivery_status: "sent", external_id: qrMsgId || null, sent_at: new Date().toISOString() });
    }
  }

  // Actualizar conversación
  const lastText = responses[responses.length - 1]?.text || "";
  await sbPatch(`/rest/v1/chat_conversations?id=eq.${convId}`, {
    last_message: lastText, last_message_at: new Date().toISOString(),
    last_sender: "agent", last_read: false, ai_typing: false,
  });
}

// ── Extracción de datos del pedido ────────────────────────────────────────────

async function extractOrderData(
  clienteTexto: string,
  histCtx: Array<{ direction: string; body: string }>,
  menuText: string,
  cfg: Record<string, unknown>
): Promise<ExtractionResult> {
  const empty: ExtractionResult = {
    producto: null, tamano: null, tipo: null, cantidad: null,
    adiciones: null, direccion: null, pago: null, nombre: null,
    confirmacion: false, upsell_rechazado: false, es_correccion: false,
  };
  if (!clienteTexto.trim()) return empty;

  const ctxLines = histCtx.map(m => `${m.direction === "in" ? "Cliente" : "Bot"}: ${m.body}`).join("\n");
  const ctxBlock = ctxLines ? `\nContexto reciente:\n${ctxLines}\n` : "";

  const pagosCfg = cfg.pagos as Record<string, unknown> | null | undefined;
  const pagosDisp: string[] = [];
  if (pagosCfg?.efectivo)  pagosDisp.push("efectivo");
  if (pagosCfg?.nequi)     pagosDisp.push("nequi");
  if (pagosCfg?.daviplata) pagosDisp.push("daviplata");
  const pagosStr = pagosDisp.length ? pagosDisp.join(" | ") : "efectivo | nequi | daviplata";

  const prompt = `Eres un extractor de datos de pedidos para restaurante. Analiza el mensaje del cliente y devuelve SOLO un JSON.
${ctxBlock}
Mensaje del cliente: "${clienteTexto}"

Menú: ${menuText}

JSON a devolver:
{
  "producto": null o "nombre del producto del menú más cercano",
  "tamano": null o "personal" o "familiar" o "unico" o "litro" o "1.5 litros",
  "tipo": null o "mixta" o "carne" o "pollo",
  "cantidad": null o número,
  "adiciones": null o "" o "descripcion",
  "direccion": null o "dirección completa",
  "pago": null o ${pagosStr},
  "nombre": null o "nombre del cliente",
  "confirmacion": false o true,
  "upsell_rechazado": false o true,
  "es_correccion": false o true
}
Reglas: extrae solo lo que el cliente dijo. null=no mencionado. adiciones null=no habló de adiciones, ""=rechazó upsell, "X"=pidió algo. confirmacion=true solo si confirma el resumen (sí/dale/correcto/etc). upsell_rechazado=true si rechazó adiciones. es_correccion=true si corrige un dato del resumen.`;

  for (let attempt = 0; attempt < 2; attempt++) {
   try {
    if (attempt > 0) await sleep(1200);
    const res = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Authorization": `Bearer ${OPENAI_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        max_tokens: 300,
        temperature: 0,
        response_format: { type: "json_object" },
      }),
    });
    if (!res.ok) {
      const errText = await res.text();
      console.error(`extractOrderData intento ${attempt+1} error:`, errText);
      if (attempt === 0) continue; // retry
      return { ...empty, _oai_error: true } as ExtractionResult;
    }

    const data    = await res.json() as Record<string, unknown>;
    const content = String(((data.choices as Array<Record<string,unknown>>)?.[0]?.message as Record<string,unknown>)?.content || "{}");
    const parsed  = JSON.parse(content) as Partial<ExtractionResult & { cantidad: number }>;

    const pagoVal   = String(parsed.pago   || "").toLowerCase().trim();
    const tamanoVal = String(parsed.tamano  || "").toLowerCase().trim();
    const tipoVal   = String(parsed.tipo    || "").toLowerCase().trim();

    return {
      producto:         typeof parsed.producto === "string" && parsed.producto.length > 0 ? parsed.producto : null,
      tamano:           ["personal","familiar","unico","litro","1.5 litros"].includes(tamanoVal) ? tamanoVal : null,
      tipo:             ["mixta","carne","pollo"].includes(tipoVal) ? tipoVal : null,
      cantidad:         typeof parsed.cantidad === "number" && parsed.cantidad > 0 ? Math.round(parsed.cantidad) : null,
      adiciones:        typeof parsed.adiciones === "string" ? parsed.adiciones : null,
      direccion:        typeof parsed.direccion === "string" && parsed.direccion.length > 0 ? parsed.direccion : null,
      pago:             pagoVal.length > 0 ? pagoVal : null,
      nombre:           typeof parsed.nombre === "string" && parsed.nombre.length > 0 ? parsed.nombre : null,
      confirmacion:     !!parsed.confirmacion,
      upsell_rechazado: !!parsed.upsell_rechazado,
      es_correccion:    !!parsed.es_correccion,
    };
  } catch (err) {
    console.error(`extractOrderData intento ${attempt+1} fetch/parse error:`, err);
    if (attempt === 0) continue; // retry
    return { ...empty, _oai_error: true } as ExtractionResult;
  }
  } // fin for
  return { ...empty, _oai_error: true } as ExtractionResult;
}

// ── Merge no-destructivo ──────────────────────────────────────────────────────

function mergeOrderState(existing: OrderState, extracted: ExtractionResult): OrderState {
  return {
    producto:         extracted.producto  ?? existing.producto,
    tamano:           extracted.tamano    ?? existing.tamano,
    tipo:             extracted.tipo      ?? existing.tipo,
    cantidad:         extracted.cantidad  ?? existing.cantidad,
    adiciones:        extracted.adiciones !== null ? extracted.adiciones : existing.adiciones,
    direccion:        extracted.direccion ?? existing.direccion,
    pago:             extracted.pago      ?? existing.pago,
    nombre:           extracted.nombre    ?? existing.nombre,
    upsell_ofrecido:  existing.upsell_ofrecido,
    upsell_rechazado: extracted.upsell_rechazado || existing.upsell_rechazado,
    resumen_enviado:  extracted.es_correccion ? false : existing.resumen_enviado,
    last_activity:    new Date().toISOString(),
  };
}

// ── Configuración de pasos ────────────────────────────────────────────────────

function getPasos(cfg: Record<string, unknown>, frases: Record<string, string>): PasoConfig[] {
  const customPasos = cfg.flujo_pasos as PasoConfig[] | null | undefined;
  if (customPasos && Array.isArray(customPasos) && customPasos.length > 0) return customPasos;
  return [
    { id: "tamano",    frase: frases.preguntar_tamano  || "¿La deseas personal o familiar? 😋" },
    { id: "tipo",      frase: frases.preguntar_tipo    || "¿La deseas mixta, de carne o de pollo? 🍟" },
    { id: "upsell",    frase: frases.upsell            || "Perfecto, ¿deseas adicionar alguna bebida, salchicha ranchera, super queso o alguna de nuestras salsas especiales? 🤩" },
    { id: "direccion", frase: frases.preguntar_destino || "Con gusto, ¿Para dónde va tu pedido? ☺️" },
    { id: "pago",      frase: frases.confirmar_pago    || "¿me confirmas si el pago es transferencia o efectivo? para pasar tu pedido a cocina 🍟☺️" },
    { id: "nombre",    frase: frases.nombre_recibir    || "¿A nombre de quién se recibe el pedido? 🍟" },
  ];
}

// ── Decisor de pasos ──────────────────────────────────────────────────────────

function decideAction(state: OrderState, pasos: PasoConfig[], menuText: string): NextAction {
  const productoLow   = (state.producto || "").toLowerCase();
  const menuLow       = menuText.toLowerCase();
  // Chequear cualquier palabra del producto (≥4 chars) para manejar "salchipapa tropical" → busca "tropical"
  const productoWords = productoLow.split(" ").filter(w => w.length >= 4);
  const necesitaTamano = productoWords.some(w => menuLow.includes(w)) &&
    (menuLow.includes("personal") || menuLow.includes("familiar"));
  const necesitaTipo  = productoLow.includes("premium") || productoLow.includes("maicito");

  for (const paso of pasos) {
    if (paso.id === "tamano" && !state.tamano && necesitaTamano) {
      return { type: "ask_field", field: "tamano", frase: paso.frase };
    }
    if (paso.id === "tipo" && !state.tipo && necesitaTipo) {
      return { type: "ask_field", field: "tipo", frase: paso.frase };
    }
    if (paso.id === "upsell" && !state.upsell_ofrecido && !state.upsell_rechazado && state.adiciones === null) {
      return { type: "ask_upsell", frase: paso.frase };
    }
    if (paso.id === "direccion" && !state.direccion) {
      return { type: "ask_field", field: "direccion", frase: paso.frase };
    }
    if (paso.id === "pago" && !state.pago) {
      return { type: "ask_field", field: "pago", frase: paso.frase };
    }
    if (paso.id === "nombre" && !state.nombre) {
      return { type: "ask_field", field: "nombre", frase: paso.frase };
    }
  }

  if (!state.resumen_enviado) return { type: "show_summary" };
  return { type: "chat", reason: "waiting_confirmation" };
}

// ── Construir resumen desde OrderState ────────────────────────────────────────

async function buildSummaryFromState(
  state: OrderState,
  cfg: Record<string, unknown>,
  branchId: string,
  domiciliosCfg: Record<string, unknown> | null | undefined
): Promise<string> {
  const frases       = (cfg.frases as Record<string, string>) || {};
  const confirmFrase = frases.resumen_confirmacion      || "¿Lo confirmamos o hay algo que cambiar?";
  const totalDesc    = frases.resumen_total_desconocido || "ya te confirmamos el total ☺️🍟";
  const plantilla    = (cfg.resumen_plantilla as string) ||
    "Listo! Tu pedido quedaría así:\n🍟 {{cantidad}}x {{producto}} {{tamano}}{{adiciones}}\n📍 {{direccion}}\n💳 {{pago}}\n{{linea_total}}\n{{confirmacion}}";

  let precioProducto = 0;
  try {
    const products = await sbGet(
      `/rest/v1/pos_products?branch_id=eq.${branchId}&available=eq.true&select=name,price,price_mode,presentations,variables`
    ) as Array<Record<string, unknown>> | null;

    if (products && state.producto) {
      const productoNorm = normalizarTexto(state.producto);
      const matched = products.find(p => {
        const pname = normalizarTexto(String(p.name || ""));
        if (pname === productoNorm) return true;
        if (pname.includes(productoNorm) || productoNorm.includes(pname)) return true;
        // Levenshtein para nombres cortos con typos
        if (pname.length >= 4 && productoNorm.length >= 4) {
          const maxDist = Math.floor(Math.min(pname.length, productoNorm.length) / 4);
          if (levenshtein(pname, productoNorm) <= maxDist) return true;
        }
        // Coincidencia por primera palabra del catálogo
        const primeraPalabra = pname.split(" ")[0];
        if (primeraPalabra.length >= 4 && productoNorm.includes(primeraPalabra)) return true;
        return false;
      });
      if (matched) {
        const pres      = (matched.presentations as Array<{name:string;price:number}>) || [];
        const vars      = (matched.variables as Array<{id:string;name:string;options:Array<{id:string;name:string;prices?:number[]}>}>) || [];
        const priceMode = String(matched.price_mode || "simple");
        if (priceMode === "matrix" && vars.length > 0 && state.tipo) {
          const varGroup = vars[0];
          const varOpt   = varGroup.options.find(o => o.name.toLowerCase() === (state.tipo || "").toLowerCase());
          if (varOpt && Array.isArray(varOpt.prices)) {
            const presIdx = pres.findIndex(p => p.name.toLowerCase() === (state.tamano || "").toLowerCase());
            precioProducto = varOpt.prices[presIdx >= 0 ? presIdx : 0] || 0;
          }
        } else {
          const presMatch = pres.find(p => p.name.toLowerCase() === (state.tamano || "").toLowerCase());
          precioProducto  = presMatch?.price || Number(matched.price) || 0;
        }
        precioProducto *= state.cantidad;
      }
    }
  } catch (err) {
    console.error("buildSummaryFromState lookup error:", err);
  }

  const domiPrecio     = state.direccion ? lookupDomiPrice(state.direccion, domiciliosCfg) : null;
  const precioDomi     = domiPrecio ?? 0;
  let lineaTotal: string;
  if (precioProducto > 0 && domiPrecio !== null) {
    const total = precioProducto + precioDomi;
    lineaTotal  = precioDomi > 0
      ? `Total: ${fmtCOP(precioProducto)} + ${fmtCOP(precioDomi)} del domicilio = ${fmtCOP(total)} :)`
      : `Total: ${fmtCOP(total)} 🍟`;
  } else {
    lineaTotal = totalDesc;
  }

  const adicionesStr   = state.adiciones && state.adiciones.length > 0 ? ` + ${state.adiciones}` : "";
  const productoDisplay = [state.producto, state.tipo].filter(Boolean).join(" ");

  return plantilla
    .replace(/\{\{cantidad\}\}/g,    String(state.cantidad || 1))
    .replace(/\{\{producto\}\}/g,    productoDisplay)
    .replace(/\{\{tamano\}\}/g,      state.tamano || "")
    .replace(/\{\{adiciones\}\}/g,   adicionesStr)
    .replace(/\{\{direccion\}\}/g,   state.direccion || "")
    .replace(/\{\{pago\}\}/g,        state.pago || "")
    .replace(/\{\{nombre\}\}/g,      state.nombre || "")
    .replace(/\{\{linea_total\}\}/g, lineaTotal)
    .replace(/\{\{confirmacion\}\}/g, confirmFrase);
}

// ── Convertir OrderState a args de createWhatsappOrder ───────────────────────

function buildOrderArgs(state: OrderState, domiPrecio: number): Record<string, unknown> {
  return {
    cliente:     state.nombre    || "Cliente WhatsApp",
    direccion:   state.direccion || "",
    pago:        state.pago      || "efectivo",
    mensaje:     "¡Pedido confirmado!",
    domi_precio: domiPrecio,
    productos: [{
      nombre:   state.producto || "",
      tamano:   capFirst(state.tamano || ""),
      tipo:     capFirst(state.tipo   || ""),
      cantidad: state.cantidad,
    }],
  };
}

function capFirst(s: string): string {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

