  if (pagos.daviplata) metodos.push("Daviplata");
  if (pagos.tarjeta)   metodos.push("Tarjeta");
  if (!metodos.length) return "";
  const lines: string[] = ["MÉTODOS DE PAGO:"];
  lines.push(`- Aceptamos: ${metodos.join(", ")}`);
